from typing import List

class WordFilter:

    def __init__(self, words: List[str]):
        self.words = words

    def f(self, pref: str, suff: str) -> int:
        for i in range(len(self.words) - 1, -1, -1):
            w = self.words[i]
            if len(w) < len(pref) or len(w) < len(suff):
                continue

            j, flag = 0, True
            for c in pref:
                if w[j] != c:
                    flag = False
                    break
                j += 1

            if not flag:
                continue

            j = len(w) - len(suff)
            for c in suff:
                if w[j] != c:
                    flag = False
                    break
                j += 1

            if flag:
                return i

        return -1

from typing import List

class WordFilter:

    def __init__(self, words: List[str]):
        self.mp = {}
        for i, w in enumerate(words):
            for j in range(len(w)):
                pref = w[:j + 1]
                for k in range(len(w)):
                    cur = pref + "$" + w[k:]
                    self.mp[cur] = i

    def f(self, pref: str, suff: str) -> int:
        s = pref + "$" + suff
        if s not in self.mp:
            return -1

        return self.mp[s]
